<script setup lang="ts">
import { computed, onMounted, ref } from 'vue'
import type { Task } from './domain/task'
import type { Project, ProjectTheme } from './domain/project'
import { childTasks, queryTasks } from './domain/taskQueries'
import AppIcon from './components/AppIcon.vue'

type Dialog={kind:'subproject'|'renameProject'|'renameChild';project?:Project;task?:Task;value:string;title:string}
const tasks=ref<Task[]>([]),projects=ref<Project[]>([]),selected=ref<Task>()
const view=ref('today'),draft=ref(''),newProjectName=ref(''),childDraft=ref(''),search=ref(''),error=ref('')
const contextMenu=ref<{project:Project;x:number;y:number}|null>(null),headerMenu=ref(false),accountMenu=ref(false)
const inputDialog=ref<Dialog|null>(null),propertiesProject=ref<Project|null>(null),moveProject=ref<Project|null>(null)
type UiSettings={workspacePath:string|null;theme:ProjectTheme;sidebarWidth:number;customTheme:{accent:string;scene:string;backgroundImage:string|null}}
const settingsOpen=ref(false),settings=ref<UiSettings|null>(null),migrating=ref(false)
const expandedTasks=ref(new Set<string>()),editingProjectId=ref<string>(),editingProjectName=ref(''),sortMode=ref<'manual'|'title'|'updated'>('manual')
const smart=[{id:'today',icon:'sun',name:'今日待办'},{id:'favorites',icon:'star',name:'收藏'},{id:'planned',icon:'calendar',name:'计划内'},{id:'completed',icon:'check-circle',name:'已完成'}]
const themes:{id:ProjectTheme;name:string;color:string;image?:boolean}[]=[{id:'mist',name:'晨雾',color:'#8da9a1'},{id:'sage',name:'青苔',color:'#4fa879'},{id:'ocean',name:'海湾',color:'#5b86c5'},{id:'rose',name:'晚樱',color:'#ca7185'},{id:'graphite',name:'墨石',color:'#667078'},{id:'forest',name:'林间',color:'#315b45',image:true},{id:'coast',name:'海岸',color:'#397a91',image:true}]
const currentProject=computed(()=>projects.value.find(item=>item.projectId===view.value))
const breadcrumbs=computed(()=>{const result:Project[]=[];let item=currentProject.value;while(item){result.unshift(item);item=item.parentId?projects.value.find(project=>project.projectId===item?.parentId):undefined}return result})
function taskCounts(projectId:string){const all=tasks.value.filter(task=>task.projectId===projectId&&task.status!=='completed');return{top:all.filter(task=>!task.parentId).length,total:all.length}}
const currentCounts=computed(()=>currentProject.value?taskCounts(currentProject.value.projectId):{top:shown.value.length,total:shown.value.length})
const projectRows=computed(()=>{const result:{project:Project;depth:number;hasChildren:boolean}[]=[];const visit=(parentId:string|null,depth:number)=>projects.value.filter(item=>item.parentId===parentId).sort((a,b)=>a.order-b.order).forEach(project=>{const hasChildren=projects.value.some(item=>item.parentId===project.projectId);result.push({project,depth,hasChildren});if(!project.collapsed)visit(project.projectId,depth+1)});visit(null,0);return result})
const viewName=computed(()=>smart.find(item=>item.id===view.value)?.name??currentProject.value?.name??'今日待办')
const shown=computed(()=>{let result=queryTasks(tasks.value,view.value);const term=search.value.trim().toLocaleLowerCase();if(term)result=result.filter(task=>[task.title,task.note,...task.tags,...childTasks(tasks.value,task.id).map(child=>child.title)].some(value=>value.toLocaleLowerCase().includes(term)));if(sortMode.value==='title')result=[...result].sort((a,b)=>a.title.localeCompare(b.title));if(sortMode.value==='updated')result=[...result].sort((a,b)=>b.updatedAt.localeCompare(a.updatedAt));return result})
const visibleTaskRows=computed(()=>{const rows:{task:Task;depth:number;hasChildren:boolean}[]=[];const visit=(task:Task,depth:number)=>{const children=childTasks(tasks.value,task.id);rows.push({task,depth,hasChildren:children.length>0});if(expandedTasks.value.has(task.id))children.forEach(child=>visit(child,depth+1))};shown.value.forEach(task=>visit(task,0));return rows})
const children=computed(()=>selected.value?childTasks(tasks.value,selected.value.id):[])
const themeClass=computed(()=>`theme-${currentProject.value?.theme??settings.value?.theme??'mist'}`)
const shellStyle=computed(()=>{const custom=settings.value?.customTheme,image=custom?.backgroundImage?.replace(/\\/g,'/');return{'--sidebar-width':`${settings.value?.sidebarWidth??262}px`,'--custom-accent':custom?.accent??'#4fa879','--custom-scene':custom?.scene??'#e9f1ef','--custom-image':image?`url("file:///${image}")`:'none'}})
function bridge(){if(!window.bearTodo)throw new Error('本地存储服务未连接，请重新启动应用');return window.bearTodo}
function closeMenus(){contextMenu.value=null;headerMenu.value=false;accountMenu.value=false}
async function load(){try{const api=bridge();await api.health();[tasks.value,projects.value,settings.value]=await Promise.all([api.listTasks(),api.listProjects(),api.getSettings()]);error.value=''}catch(reason){error.value=message(reason)}}
function defaultProject(){return projects.value.find(item=>item.name==='默认项目'&&item.parentId===null)??projects.value[0]}
async function add(){const title=draft.value.trim(),project=currentProject.value??defaultProject();if(!title||!project)return;try{const task=await bridge().createTask(title,project.projectId);tasks.value.unshift(task);draft.value='';selected.value=task}catch(reason){error.value=message(reason)}}
async function save(task:Task,patch:Partial<Task>){const original=task.revision;Object.assign(task,patch);try{Object.assign(task,await bridge().saveTask(task,original));error.value=''}catch(reason){error.value=message(reason);await load()}}
async function toggleDone(task:Task){await save(task,{status:task.status==='completed'?'active':'completed',completedAt:task.status==='completed'?null:new Date().toISOString()})}
async function addChildTask(){const parent=selected.value,title=childDraft.value.trim();if(!parent||!title)return;try{tasks.value.push(await bridge().createTask(title,parent.projectId,parent.id));expandedTasks.value=new Set(expandedTasks.value).add(parent.id);childDraft.value=''}catch(reason){error.value=message(reason)}}
async function createProject(parentId:string|null=null,name?:string){const value=(name??newProjectName.value).trim();if(!value)return;try{projects.value.push(await bridge().createProject(value,parentId));newProjectName.value='';closeMenus()}catch(reason){error.value=message(reason)}}
function openContext(event:MouseEvent,project:Project){event.preventDefault();closeMenus();contextMenu.value={project,x:event.clientX,y:event.clientY}}
function openDialog(kind:Dialog['kind'],project?:Project,task?:Task){closeMenus();inputDialog.value={kind,project,task,value:kind==='subproject'?'':project?.name??task?.title??'',title:kind==='subproject'?`在“${project?.name}”中新增子项目`:kind==='renameChild'?'重命名子任务':'重命名项目'}}
async function confirmInput(){const dialog=inputDialog.value,value=dialog?.value.trim();if(!dialog||!value)return;try{if(dialog.kind==='subproject'&&dialog.project)await createProject(dialog.project.projectId,value);else if(dialog.kind==='renameProject'&&dialog.project)Object.assign(dialog.project,await bridge().renameProject(dialog.project.projectId,value));else if(dialog.task)await save(dialog.task,{title:value});inputDialog.value=null}catch(reason){error.value=message(reason)}}
function startInlineRename(project:Project){editingProjectId.value=project.projectId;editingProjectName.value=project.name;requestAnimationFrame(()=>document.querySelector<HTMLInputElement>('.project-inline-input')?.select())}
async function finishInlineRename(saveValue=true){const project=projects.value.find(item=>item.projectId===editingProjectId.value),name=editingProjectName.value.trim();editingProjectId.value=undefined;if(!saveValue||!project||!name||name===project.name)return;try{Object.assign(project,await bridge().renameProject(project.projectId,name))}catch(reason){error.value=message(reason)}}
async function toggleProject(project:Project){try{Object.assign(project,await bridge().updateProject(project.projectId,{collapsed:!project.collapsed}))}catch(reason){error.value=message(reason)}}
function toggleTask(id:string){const next=new Set(expandedTasks.value);next.has(id)?next.delete(id):next.add(id);expandedTasks.value=next}
function openProperties(project:Project){closeMenus();propertiesProject.value={...project}}
async function saveProperties(){const draft=propertiesProject.value;if(!draft)return;try{const next=await bridge().updateProject(draft.projectId,{name:draft.name,icon:draft.icon,description:draft.description,sidebarColor:draft.sidebarColor,theme:draft.theme});const existing=projects.value.find(item=>item.projectId===draft.projectId);if(existing)Object.assign(existing,next);propertiesProject.value=null}catch(reason){error.value=message(reason)}}
async function moveTo(parentId:string|null){const project=moveProject.value;if(!project)return;try{const next=await bridge().moveProject(project.projectId,parentId);Object.assign(project,next);moveProject.value=null}catch(reason){error.value=message(reason)}}
async function openSettings(){closeMenus();try{settings.value=await bridge().getSettings();settingsOpen.value=true}catch(reason){error.value=message(reason)}}
async function setGlobalTheme(theme:ProjectTheme){try{settings.value=await bridge().setPreferences({theme})}catch(reason){error.value=message(reason)}}
async function savePreferences(patch:Partial<Pick<UiSettings,'theme'|'sidebarWidth'|'customTheme'>>){try{settings.value=await bridge().setPreferences(patch)}catch(reason){error.value=message(reason)}}
async function chooseBackground(){try{const path=await bridge().chooseThemeBackground();if(path&&settings.value)await savePreferences({theme:'custom',customTheme:{...settings.value.customTheme,backgroundImage:path}})}catch(reason){error.value=message(reason)}}
async function changeWorkspace(){migrating.value=true;try{const result=await bridge().changeWorkspace();if(!result.canceled){settings.value=await bridge().getSettings();await load();selected.value=undefined;view.value='today'}}catch(reason){error.value=message(reason)}finally{migrating.value=false}}
async function archiveProject(project:Project){if(!window.confirm(`归档项目“${project.name}”及其目录内容？`))return;try{await bridge().archiveProject(project.projectId);const ids=new Set([project.projectId]);let changed=true;while(changed){changed=false;for(const item of projects.value)if(item.parentId&&ids.has(item.parentId)&&!ids.has(item.projectId)){ids.add(item.projectId);changed=true}}projects.value=projects.value.filter(item=>!ids.has(item.projectId));if(ids.has(view.value))view.value='today';closeMenus()}catch(reason){error.value=message(reason)}}
function message(reason:unknown){return reason instanceof Error?reason.message:'操作失败，请重新加载'}
onMounted(load)
</script>

<template><main class="shell" :class="[themeClass,{'has-detail':selected}]" :style="shellStyle" @click="closeMenus"><header class="titlebar"><div class="drag-region"><b>熊智ToDo</b><span>本地 Markdown 工作台</span></div><div class="window-controls"><button aria-label="最小化" @click="bridge().minimizeWindow()"><AppIcon name="minimize"/></button><button aria-label="最大化或还原" @click="bridge().toggleMaximizeWindow()"><AppIcon name="maximize" :size="15"/></button><button class="close" aria-label="关闭" @click="bridge().closeWindow()"><AppIcon name="close" :size="16"/></button></div></header>
  <aside class="nav" aria-label="任务与项目导航">
    <label class="search"><AppIcon name="search" :size="16"/><input v-model="search" placeholder="搜索任务、标签或子任务" aria-label="全局搜索"/></label>
    <button v-for="item in smart" :key="item.id" class="smart-row" :class="{selected:view===item.id}" @click="view=item.id"><AppIcon :name="item.icon"/><span class="row-label">{{item.name}}</span><small>{{queryTasks(tasks,item.id).length}}</small></button><hr/><div class="section-title">项目</div>
    <div class="project-tree"><div v-for="row in projectRows" :key="row.project.projectId" class="list-row" :class="{selected:view===row.project.projectId}" :style="{'--depth':row.depth,'--row-color':row.project.sidebarColor}" @contextmenu="openContext($event,row.project)"><button class="tree-toggle" :class="{hidden:!row.hasChildren}" :aria-label="row.project.collapsed?'展开子项目':'折叠子项目'" @click.stop="toggleProject(row.project)"><AppIcon :name="row.project.collapsed?'chevron-right':'chevron-down'" :size="16"/></button><button class="list-main" @click="view=row.project.projectId" @dblclick.stop="startInlineRename(row.project)"><span class="project-icon"><AppIcon v-if="row.project.icon==='📁'" name="folder" :size="18"/><template v-else>{{row.project.icon}}</template></span><input v-if="editingProjectId===row.project.projectId" v-model="editingProjectName" class="project-inline-input" @click.stop @blur="finishInlineRename()" @keydown.enter.prevent="finishInlineRename()" @keydown.esc.prevent="finishInlineRename(false)"/><b v-else>{{row.project.name}}</b><small class="project-counts" title="顶级任务 / 全部任务">{{taskCounts(row.project.projectId).top}} / {{taskCounts(row.project.projectId).total}}</small></button></div></div>
    <div class="spacer"/><form class="new-row" @submit.prevent="createProject(null)"><input v-model="newProjectName" placeholder="新建项目" aria-label="新项目名称"/><button aria-label="创建项目"><AppIcon name="plus"/></button></form><div class="account-wrap"><button class="account-block" @click.stop="accountMenu=!accountMenu"><span class="avatar">熊</span><span><b>本地用户</b><small>本地工作区</small></span><AppIcon name="chevron-up" :size="16"/></button><div v-if="accountMenu" class="account-menu floating-menu" @click.stop><button disabled><AppIcon name="user"/><span>管理账号</span><small>未来功能</small></button><button @click="openSettings"><AppIcon name="settings"/><span>设置</span></button><button disabled><AppIcon name="sync"/><span>同步</span><small>未来功能</small></button></div></div>
  </aside>
  <section class="list"><header class="list-header"><div class="heading-block"><nav v-if="breadcrumbs.length" class="breadcrumbs" aria-label="项目路径"><template v-for="(project,index) in breadcrumbs" :key="project.projectId"><button @click="view=project.projectId">{{project.name}}</button><AppIcon v-if="index<breadcrumbs.length-1" name="chevron-right" :size="14"/></template></nav><h1 v-else>{{viewName}}</h1><p>{{new Date().toLocaleDateString('zh-CN',{month:'long',day:'numeric',weekday:'long'})}}<template v-if="currentProject?.description"> · {{currentProject.description}}</template></p></div><div class="header-actions"><span class="header-counts"><b>{{currentCounts.top}}</b> 顶级 <i></i><b>{{currentCounts.total}}</b> 全部</span><button v-if="currentProject" class="more" aria-label="项目菜单" @click.stop="headerMenu=!headerMenu"><AppIcon name="more" :size="21"/></button></div><div v-if="headerMenu&&currentProject" class="header-menu floating-menu" @click.stop><button @click="openDialog('renameProject',currentProject)"><AppIcon name="edit"/><span>重命名项目</span></button><button @click="moveProject=currentProject;headerMenu=false"><AppIcon name="move"/><span>将项目移动到</span></button><div class="menu-label">排序方式</div><button v-for="option in [{id:'manual',name:'手动排序'},{id:'title',name:'按标题'},{id:'updated',name:'最近更新'}]" :key="option.id" @click="sortMode=option.id as typeof sortMode"><span class="menu-check"><AppIcon v-if="sortMode===option.id" name="check" :size="15"/></span><span>{{option.name}}</span></button><div class="menu-label">项目主题</div><div class="theme-swatches"><button v-for="theme in [...themes,...(settings?.customTheme?[{id:'custom' as ProjectTheme,name:'自定义',color:settings.customTheme.accent}]:[])]" :key="theme.id" :style="{background:theme.color}" :aria-label="theme.name" @click="currentProject&&bridge().updateProject(currentProject.projectId,{theme:theme.id}).then(next=>Object.assign(currentProject!,next))"></button></div><button class="danger" @click="archiveProject(currentProject)"><AppIcon name="archive"/><span>归档</span></button></div></header><p v-if="error" class="error" role="alert">{{error}}</p><div v-if="view!=='completed'" class="add"><AppIcon name="plus"/><input v-model="draft" @keyup.enter="add" placeholder="添加任务" aria-label="任务标题"/></div><div class="cards"><article v-for="row in visibleTaskRows" :key="row.task.id" :style="{'--task-depth':row.depth}" :class="{active:selected?.id===row.task.id,child:row.depth>0}" @click="selected=row.task"><button v-if="row.hasChildren" class="task-expand" :aria-label="expandedTasks.has(row.task.id)?'折叠子任务':'展开子任务'" @click.stop="toggleTask(row.task.id)"><AppIcon :name="expandedTasks.has(row.task.id)?'chevron-down':'chevron-right'" :size="16"/></button><span v-else class="task-expand placeholder"></span><button class="circle" :class="{done:row.task.status==='completed'}" :aria-label="row.task.status==='completed'?'恢复任务':'完成任务'" @click.stop="toggleDone(row.task)"><AppIcon v-if="row.task.status==='completed'" name="check" :size="14"/></button><div><strong :class="{strike:row.task.status==='completed'}">{{row.task.title}}</strong><small>{{row.depth?'子任务 · ':''}}{{row.task.tags.map(tag=>'#'+tag).join(' ')||projects.find(project=>project.projectId===row.task.projectId)?.name||'任务'}}</small></div><button class="star" :class="{filled:row.task.favorite}" :aria-label="row.task.favorite?'取消收藏':'收藏任务'" @click.stop="save(row.task,{favorite:!row.task.favorite})"><AppIcon name="star" :size="19"/></button></article><div v-if="!visibleTaskRows.length" class="empty"><b>{{search?'没有匹配结果':'这里还没有任务'}}</b><span>{{search?'尝试其他关键词':'从添加一件小事开始'}}</span></div></div></section>
  <aside v-if="selected" class="detail" aria-label="任务详情"><button class="detail-close" aria-label="关闭任务详情" @click="selected=undefined"><AppIcon name="close"/></button><div class="task-title"><button class="circle" :class="{done:selected.status==='completed'}" @click="toggleDone(selected)"><AppIcon v-if="selected.status==='completed'" name="check" :size="14"/></button><input v-model="selected.title" @change="save(selected,{title:selected.title})" aria-label="任务标题"/><button class="star" :class="{filled:selected.favorite}" @click="save(selected,{favorite:!selected.favorite})"><AppIcon name="star" :size="19"/></button></div><div class="steps" aria-label="子任务"><h3>子任务</h3><div v-for="child in children" :key="child.id"><button class="circle" :class="{done:child.status==='completed'}" @click="toggleDone(child)"><AppIcon v-if="child.status==='completed'" name="check" :size="14"/></button><button class="step-name" :class="{strike:child.status==='completed'}" @dblclick="openDialog('renameChild',undefined,child)">{{child.title}}</button></div><form @submit.prevent="addChildTask"><input v-model="childDraft" placeholder="添加子任务" aria-label="子任务名称"/><button aria-label="添加子任务"><AppIcon name="plus"/></button></form></div><button disabled><AppIcon name="clock"/><span>提醒我</span></button><button disabled><AppIcon name="calendar"/><span>添加截止日期</span></button><button disabled><AppIcon name="repeat"/><span>重复</span></button><textarea v-model="selected.note" @change="save(selected,{note:selected.note})" placeholder="添加备注"></textarea><small>创建于 {{new Date(selected.createdAt).toLocaleDateString()}}</small></aside>
  <div v-if="contextMenu" class="context-menu floating-menu" :style="{left:contextMenu.x+'px',top:contextMenu.y+'px'}" @click.stop><button @click="openDialog('subproject',contextMenu.project)"><AppIcon name="plus"/><span>新增子项目</span></button><button @click="openDialog('renameProject',contextMenu.project)"><AppIcon name="edit"/><span>重命名</span></button><button @click="openProperties(contextMenu.project)"><AppIcon name="settings"/><span>属性</span></button><button class="danger" @click="archiveProject(contextMenu.project)"><AppIcon name="archive"/><span>归档</span></button></div>
  <div v-if="inputDialog" class="modal-backdrop" @click.self="inputDialog=null"><form class="modal compact" @submit.prevent="confirmInput"><h2>{{inputDialog.title}}</h2><input v-model="inputDialog.value" autofocus aria-label="名称"/><div class="modal-actions"><button type="button" @click="inputDialog=null">取消</button><button class="primary">确定</button></div></form></div>
  <div v-if="propertiesProject" class="modal-backdrop" @click.self="propertiesProject=null"><form class="modal properties-modal" @submit.prevent="saveProperties"><h2>项目属性</h2><div class="form-grid"><label>项目名称<input v-model="propertiesProject.name"/></label><label>项目图标<input v-model="propertiesProject.icon" maxlength="4"/></label><label class="wide">项目描述<textarea v-model="propertiesProject.description" placeholder="这个项目用于……"></textarea></label><label>侧边栏主题色<input v-model="propertiesProject.sidebarColor" type="color"/></label><fieldset><legend>项目主题</legend><div class="theme-options"><button v-for="theme in themes" :key="theme.id" type="button" :class="{selected:propertiesProject.theme===theme.id}" @click="propertiesProject.theme=theme.id"><i :style="{background:theme.color}"></i>{{theme.name}}</button></div></fieldset></div><div class="modal-actions"><button type="button" @click="propertiesProject=null">取消</button><button class="primary">保存属性</button></div></form></div>
  <div v-if="moveProject" class="modal-backdrop" @click.self="moveProject=null"><section class="modal compact"><h2>移动“{{moveProject.name}}”</h2><div class="move-list"><button @click="moveTo(null)">工作目录根级</button><button v-for="project in projects.filter(item=>item.projectId!==moveProject?.projectId)" :key="project.projectId" @click="moveTo(project.projectId)">{{project.icon}} {{project.name}}</button></div><div class="modal-actions"><button @click="moveProject=null">取消</button></div></section></div>
  <div v-if="settingsOpen&&settings" class="modal-backdrop" @click.self="settingsOpen=false"><section class="modal settings-modal"><h2>设置</h2><label>工作目录</label><div class="path-box">{{settings.workspacePath}}</div><p>迁移校验成功后切换到新目录并删除旧工作目录。</p><button class="primary" :disabled="migrating" @click="changeWorkspace">{{migrating?'正在迁移…':'修改工作目录并迁移'}}</button><fieldset><legend>侧边栏宽度</legend><div class="range-setting"><input v-model.number="settings.sidebarWidth" type="range" min="220" max="380" step="4" @change="savePreferences({sidebarWidth:settings.sidebarWidth})"/><output>{{settings.sidebarWidth}} px</output></div></fieldset><fieldset><legend>全局主题</legend><div class="theme-options"><button v-for="theme in themes" :key="theme.id" :class="{selected:settings.theme===theme.id}" @click="setGlobalTheme(theme.id)"><i :class="{'image-theme':theme.image}" :style="{background:theme.color}"></i>{{theme.name}}</button><button :class="{selected:settings.theme==='custom'}" @click="savePreferences({theme:'custom'})"><i :style="{background:settings.customTheme.accent}"></i>自定义</button></div></fieldset><fieldset class="custom-theme"><legend>自定义主题</legend><div class="custom-colors"><label>强调色<input v-model="settings.customTheme.accent" type="color" @change="savePreferences({theme:'custom',customTheme:settings.customTheme})"/></label><label>背景色<input v-model="settings.customTheme.scene" type="color" @change="savePreferences({theme:'custom',customTheme:settings.customTheme})"/></label></div><button @click="chooseBackground">选择本地背景图片</button><button v-if="settings.customTheme.backgroundImage" @click="savePreferences({customTheme:{...settings.customTheme,backgroundImage:null}})">移除背景图片</button><small v-if="settings.customTheme.backgroundImage">{{settings.customTheme.backgroundImage}}</small></fieldset><div class="modal-actions"><button @click="settingsOpen=false">关闭</button></div></section></div>
</main></template>
